using System;using System.IO;using System.Linq;using System.Drawing;using DoomSNESed;
namespace DoomSNESed { public static class MusicHudTests {
static int checks;static void Check(bool ok,string message){if(!ok)throw new Exception(message);checks++;Console.WriteLine("PASS "+message);}
public static void Run(string path,string output){checks=0;string dir=Path.Combine(output,"music-hud-07");Directory.CreateDirectory(dir);var rom=new Rom(path,Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"editor-data"));
foreach(var asset in HudAssets.All().Where(a=>a.Screen!=PickupFont.Screen)){byte[] native=HudAssets.Data(rom.Bytes,asset.Screen);var replacement=new GraphicReplacement{Screen=asset.Screen,Width=asset.Width,Height=asset.Height,Pixels=HudAssets.Pixels(native,asset.Width,asset.Height)};Check(HudAssets.Tiles(replacement).SequenceEqual(native),"native planar round-trip "+asset.Name);using(var image=HudAssets.Preview(rom,asset.Screen,null)){string file=dir+"/asset-"+asset.Screen+".png";image.Save(file);var imported=HudAssets.Import(rom,asset,file);Check(HudAssets.Tiles(imported).SequenceEqual(native),"PNG round-trip preserves native palette indices "+asset.Name);}for(int i=0;i<replacement.Pixels.Length;i++)replacement.Pixels[i]=(byte)((i+asset.Screen)%16);rom.Project.Graphics.Add(replacement);}
rom.Project.RetailAssets=true;var imageRom=rom.Compile();foreach(var asset in HudAssets.All().Where(a=>a.Screen!=PickupFont.Screen))Check(HudAssets.Data(imageRom,asset.Screen).SequenceEqual(HudAssets.Tiles(rom.Project.Graphics.Single(g=>g.Screen==asset.Screen))),"ROM replacement round-trip "+asset.Name);rom.SavePatch(dir+"/hud.dse",imageRom);rom.SaveProject(dir+"/hud.sned");File.WriteAllBytes(dir+"/hud.sfc",imageRom);
var input=new ImportedMusic{Name="Music mapping fixture",Seconds=3,Report=""};foreach(int key in new[]{36,38,40,41,42,44,46,49,51,53,57})input.Notes.Add(new MusicNote{Channel=9,Key=key,Start=0,End=1,Velocity=100});input.Notes.Add(new MusicNote{Channel=0,Program=34,Key=40,Start=0,End=1,Velocity=100});input.Notes.Add(new MusicNote{Channel=1,Program=29,Key=52,Start=0,End=1,Velocity=100});var mapping=MusicBank.Automatic(rom.Bytes,input);var bank=MusicBank.Read(rom.Bytes,mapping.Bank);foreach(var group in input.Notes.GroupBy(n=>new{n.Channel,n.Program,Key=n.Channel==9?n.Key:-1})){var assignment=mapping.Assignments.Single(a=>a.Channel==group.Key.Channel&&a.Program==group.Key.Program&&a.Key==group.Key.Key);Check(NativeVoicing.Percussion(assignment.Patch)==(group.Key.Channel==9),"automatic mapping separates melody / percussion "+group.Key);}
Check(MusicBank.Closest(MusicBank.Read(rom.Bytes,4),new MusicNote{Channel=0,Program=34})==45,"retail E1M1 bass uses patch 45, not kick 46");Check(MusicBank.Closest(MusicBank.Read(rom.Bytes,4),new MusicNote{Channel=9,Key=36})==46,"retail E1M1 kick uses patch 46");Check(NativeVoicing.Pitch(new MusicNote{Channel=9,Key=40},42)==75,"retail snare native pitch 75");Check(NativeVoicing.Pitch(new MusicNote{Channel=9,Key=46},47)==68,"retail hi-hat fallback native pitch 68");
foreach(var a in mapping.Assignments)a.Mute=true;var silent=MusicImport.Convert(input,"E1M1",6,3,true,mapping);AudioBuild.ValidateMusic(silent);int rate;var pcm=NativeAudio.Render(rom.Bytes,MusicBank.PreviewRam(rom.Bytes,silent),0,mapping.Song,2,out rate);Check(pcm.All(v=>v==0),"mute all produces silent native SPC audio including percussion");foreach(var a in mapping.Assignments)a.Mute=a.Channel==9;Check(input.Notes.Where(n=>!MusicBank.Muted(mapping,n)).All(n=>n.Channel!=9),"source and converted filters mute every percussion key");
foreach(var b in MusicBank.All(rom.Bytes))Check(b.Instruments.Any(i=>!NativeVoicing.Percussion(i.Id)),"melodic instruments in native bank "+b.Module);
File.WriteAllText(dir+"/results.txt","PASS "+checks+" graphics and music checks\r\n");}
}

}